JSPiNativeErrorConstructorNameStatus JS_PiGetNativeErrorConstructorName(
    JSContext *ctx, JSValueConst error, JSValue *owned_name)
{
    JSObject *receiver, *current;
    JSValue value, name;
    int found;
    assert(ctx != NULL && owned_name != NULL);
    *owned_name = JS_UNDEFINED;
    if (!JS_IsError(error))
        return JS_PI_ERROR_CONSTRUCTOR_NAME_NOT_NATIVE_ERROR;
    receiver = JS_VALUE_GET_OBJ(error);
    if (receiver->u.native_error.constructor_provenance != 1)
        return JS_PI_ERROR_CONSTRUCTOR_NAME_UNSUPPORTED;

    if (!receiver->is_prototype) {
        assert(JS_IsString(receiver->u.native_error.constructor_name));
        *owned_name = js_dup(receiver->u.native_error.constructor_name);
        return JS_PI_ERROR_CONSTRUCTOR_NAME_FOUND;
    }

    /* The original prototype-map restriction suppresses the retained base
     * constructor fast path. Walk physical prototype links only. */
    for (current = receiver; current != NULL; current = current->shape->proto) {
        if (!js_pi_constructor_own_data(current, JS_ATOM_Symbol_toStringTag,
                                         &value))
            return JS_PI_ERROR_CONSTRUCTOR_NAME_UNSUPPORTED;
        if (JS_IsString(value)) {
            *owned_name = js_dup(value);
            return JS_PI_ERROR_CONSTRUCTOR_NAME_FOUND;
        }
        if (current == receiver)
            continue;
        if (!js_pi_constructor_own_data(current, JS_ATOM_constructor, &value))
            return JS_PI_ERROR_CONSTRUCTOR_NAME_UNSUPPORTED;
        found = js_pi_constructor_debug_name(ctx, value, &name);
        if (found < 0)
            return JS_PI_ERROR_CONSTRUCTOR_NAME_UNSUPPORTED;
        if (found > 0) {
            *owned_name = js_dup(name);
            return JS_PI_ERROR_CONSTRUCTOR_NAME_FOUND;
        }
    }
    /* Exact native JSError class_name fallback. The protected intrinsic Error
     * name is already a real string, so this remains allocation-free. */
    name = ctx->pi_error_constructor_name[JS_PLAIN_ERROR];
    if (!JS_IsString(name))
        return JS_PI_ERROR_CONSTRUCTOR_NAME_UNSUPPORTED;
    *owned_name = js_dup(name);
    return JS_PI_ERROR_CONSTRUCTOR_NAME_FOUND;
}

void JS_PiRequestExecutionTermination(JSRuntime *rt)
{
#ifdef CONFIG_ATOMICS
    atomic_store(&rt->pi_termination_requested, true);
#else
    rt->pi_termination_requested = true;
#endif
}

bool JS_PiIsExecutionTerminating(JSRuntime *rt)
{
    return rt->pi_termination_in_flight &&
           JS_PiIsExecutionTermination(rt->current_exception);
}

uint64_t JS_PiExecutionTerminationGeneration(JSRuntime *rt)
{
    return rt->pi_termination_generation;
}

void JS_PiCancelExecutionTermination(JSRuntime *rt)
{
#ifdef CONFIG_ATOMICS
    atomic_store(&rt->pi_termination_requested, false);
#else
    rt->pi_termination_requested = false;
#endif
    /* V8 clears the request even when no actual termination is pending.
       Its event cancellation is conditional on the private pending event;
       an event held only by a native cleanup owner is not that condition. */
    if (!JS_PiIsExecutionTerminating(rt))
        return;
    rt->current_exception = JS_UNINITIALIZED;
    rt->pi_termination_in_flight = false;
}

int JS_PiCheckExecutionTermination(JSContext *ctx)
{
    JSRuntime *rt = ctx->rt;
    bool requested;

    if (rt->pi_termination_in_flight) {
        /* Reentry while the token is detached republishes the same event.
           It does not create another generation or a replacement Error. */
        JS_Throw(ctx, js_pi_termination_token());
        return -1;
    }
    if (JS_PiIsExecutionTermination(rt->current_exception))
        return -1; /* cancelled native abrupt completion, not a new event */
    if (!js_pi_termination_requested(rt))
        return 0;
    /* Existing ordinary/fatal pending-entry policy is retained. A request
       waits until the earlier real event has been handled by its owner. */
    if (JS_HasException(ctx))
        return -1;
#ifdef CONFIG_ATOMICS
    requested = atomic_exchange(&rt->pi_termination_requested, false);
#else
    requested = rt->pi_termination_requested;
    rt->pi_termination_requested = false;
#endif
    if (!requested)
        return 0;

test "VM native Error constructor actual native origin survives released foreign realm and retires with Error" {
    var f: Fixture = .{}; try f.init(); defer f.deinit();
    var foreign: ?*c.JSContext = c.JS_NewContext(f.runtime.?) orelse return error.OutOfMemory;
    defer if (foreign) |context| c.JS_FreeContext(context);
    var value = c.pi_js_undefined(); defer c.JS_FreeValue(f.context.?, value);
    var constructor = c.pi_js_undefined(); defer c.JS_FreeValue(f.context.?, constructor);
    const global_object = try f.checked(c.JS_GetGlobalObject(foreign.?));
    const selected_constructor = c.JS_GetPropertyStr(foreign.?, global_object, "Error");
    c.JS_FreeValue(foreign.?, global_object);
    constructor = try f.checked(selected_constructor);
    const marker = try f.newMarker();
    // DefinePropertyValueStr consumes the marker, including on failure.
    try std.testing.expectEqual(@as(c_int, 1),
        c.JS_DefinePropertyValueStr(foreign.?, constructor, "nativeLifetimeWitness", marker, c.JS_PROP_C_W_E));
    value = try f.checked(c.JS_NewError(foreign.?));
    {
        // The raw context has no native stack hooks or prepareStackTrace.
        // Its real ErrorData is a String, so it cannot retain the foreign realm.
        const stack_data = try f.checked(c.JS_GetPropertyStr(foreign.?, value, "stack"));
        defer c.JS_FreeValue(f.context.?, stack_data);
        try std.testing.expect(c.JS_IsString(stack_data));
