    ctx->native_error_proto[i] = proto;

Handle<Map> Map::GetDerivedMap(Isolate* isolate, DirectHandle<Map> from,
                               DirectHandle<JSReceiver> prototype) {
  DCHECK(IsUndefined(from->GetBackPointer()));

  if (IsJSObjectThatCanBeTrackedAsPrototype(*prototype)) {
    DirectHandle<JSObject> js_prototype = Cast<JSObject>(prototype);
    if (!js_prototype->map()->is_prototype_map()) {
      JSObject::OptimizeAsPrototype(js_prototype);
    }
    DirectHandle<PrototypeInfo> info =
        Map::GetOrCreatePrototypeInfo(js_prototype, isolate);
    Tagged<HeapObject> map_obj;
    Handle<Map> map;
    if (info->GetDerivedMap(from).GetHeapObjectIfWeak(&map_obj)) {
      map = handle(Cast<Map>(map_obj), isolate);
    } else {
      map = Map::CopyInitialMap(isolate, from);
      map->set_new_target_is_base(false);
      if (map->prototype() != *prototype) {
        Map::SetPrototype(isolate, map, prototype);
      }
      PrototypeInfo::AddDerivedMap(info, map, isolate);
    }
    return map;
  }

  // The TransitionToPrototype map will not have new_target_is_base reset. But
  // we don't need it to for proxies.
  return Map::TransitionRootMapToPrototypeForNewObject(isolate, from,
                                                       prototype);
}

MaybeHandle<Map> JSFunction::GetDerivedMap(
    Isolate* isolate, DirectHandle<JSFunction> constructor,
    DirectHandle<JSReceiver> new_target) {
  EnsureHasInitialMap(constructor);

  DirectHandle<Map> constructor_initial_map(constructor->initial_map(),
                                            isolate);
  if (*new_target == *constructor) {
    return indirect_handle(constructor_initial_map, isolate);
  }

  DirectHandle<Map> result_map;
  // Fast case, new.target is a subclass of constructor. The map is cacheable
  // (and may already have been cached). new.target.prototype is guaranteed to
  // be a JSReceiver.
  InstanceType new_target_instance_type = new_target->map()->instance_type();
  if (InstanceTypeChecker::IsJSFunction(new_target_instance_type)) {
    DirectHandle<JSFunction> function = Cast<JSFunction>(new_target);
    if (FastInitializeDerivedMap(isolate, function, constructor,
                                 constructor_initial_map)) {
      return handle(function->initial_map(), isolate);
    }
  }

  // Slow path, new.target is either a proxy object or can't cache the map.
  // new.target.prototype is not guaranteed to be a JSReceiver, and may need to
  // fall back to the intrinsicDefaultProto.
  DirectHandle<Object> prototype;
  if (InstanceTypeChecker::IsJSFunction(new_target_instance_type) &&
      Cast<JSFunction>(new_target)->has_prototype_slot()) {
    DirectHandle<JSFunction> function = Cast<JSFunction>(new_target);
    // Make sure the new.target.prototype is cached.
    EnsureHasInitialMap(function);
    prototype = direct_handle(function->prototype(), isolate);
  } else {
    // The new.target is a constructor but it's not a JSFunction with
    // a prototype slot, so get the prototype property.
    DirectHandle<String> prototype_string =
        isolate->factory()->prototype_string();
    ASSIGN_RETURN_ON_EXCEPTION(
        isolate, prototype,
        JSReceiver::GetProperty(isolate, new_target, prototype_string));
    // The above prototype lookup might change the constructor and its
    // prototype, hence we have to reload the initial map.
    EnsureHasInitialMap(constructor);
    constructor_initial_map =
        direct_handle(constructor->initial_map(), isolate);
  }

  // If prototype is not a JSReceiver, fetch the intrinsicDefaultProto from the
  // correct realm. Rather than directly fetching the .prototype, we fetch the
  // constructor that points to the .prototype. This relies on
  // constructor.prototype being FROZEN for those constructors.
  if (!IsJSReceiver(*prototype)) {
    DirectHandle<NativeContext> native_context;
    ASSIGN_RETURN_ON_EXCEPTION(isolate, native_context,
                               JSReceiver::GetFunctionRealm(new_target));
    DirectHandle<Object> maybe_index = JSReceiver::GetDataProperty(
        isolate, constructor,
        isolate->factory()->native_context_index_symbol());
    int index = IsSmi(*maybe_index) ? Smi::ToInt(*maybe_index)
                                    : Context::OBJECT_FUNCTION_INDEX;
    DirectHandle<JSFunction> realm_constructor(
        Cast<JSFunction>(native_context->get(index)), isolate);
    prototype = direct_handle(realm_constructor->prototype(), isolate);
  }
  DCHECK_EQ(constructor_initial_map->constructor_or_back_pointer(),
            *constructor);
  return Map::GetDerivedMap(isolate, constructor_initial_map,
                            Cast<JSReceiver>(prototype));

static void js_pi_record_error_constructor(JSContext *ctx, JSValueConst error,
                                           int kind, JSValueConst constructor,
                                           JSValueConst new_target)
{
    JSObject *object;
    JSValue base, name;
    if (!JS_IsError(error))
        return;
    assert(kind >= 0 && kind <= JS_PLAIN_ERROR);
    object = JS_VALUE_GET_OBJ(error);
    assert(JS_IsUndefined(object->u.native_error.constructor));
    assert(JS_IsUndefined(object->u.native_error.constructor_name));
    base = js_pi_intrinsic_error_constructor(ctx, kind);
    name = ctx->pi_error_constructor_name[kind];
    if (!JS_IsObject(base) || !JS_IsObject(constructor) ||
        JS_VALUE_GET_OBJ(base) != JS_VALUE_GET_OBJ(constructor) ||
        !JS_IsString(name))
        return;
    object->u.native_error.constructor = js_dup(base);
    object->u.native_error.constructor_name = js_dup(name);
    object->u.native_error.constructor_provenance =
        JS_IsObject(new_target) &&
        JS_VALUE_GET_OBJ(new_target) == JS_VALUE_GET_OBJ(base)
            ? 1 : 2;

JSValue value, name;
int found;
assert(ctx != NULL && owned_name != NULL);
*owned_name = JS_UNDEFINED;
if (!JS_IsError(error))
    return JS_PI_ERROR_CONSTRUCTOR_NAME_NOT_NATIVE_ERROR;
receiver = JS_VALUE_GET_OBJ(error);
if (receiver->u.native_error.constructor_provenance != 1)
    return JS_PI_ERROR_CONSTRUCTOR_NAME_UNSUPPORTED;

